#pragma once

#include "shared/features/player/player_buff.h"

#include <cstdint>
#include <string_view>
#include <vector>

namespace KCDC::Shared::Game {
    /**
     * One row of `Libs/Tables/item/body_part.xml`: a limb of one race, and
     * the injury buff a blow to it applies.
     *
     * Generated by `tools/generate_body_part_catalog.py`; the server has no
     * game module to read the table from.
     */
    struct BodyPartEntry {
        /** `body_part_name`, e.g. "arm_left", "horse_legs". */
        std::string_view name;

        /**
         * The game's own camelCase spelling -- "leftArm" -- from the
         * `injuredBodyPart` rows of `rpg_context_tag.xml`. Only the six human
         * limbs have one, and it is what the scripting API names a limb by.
         */
        std::string_view scriptName;

        /**
         * `injury_buff_id`, in the encoding a buff report carries, so a
         * reported buff is matched against the six limbs without a trip
         * through the 929-row buff table. Invalid for a part nothing injures.
         */
        RPC::BuffId injuryBuff;

        /** `body_part_id`. Zero is never a row, so it doubles as "no body part". */
        std::uint8_t id;

        /** `race_id`; 0 is human. */
        std::uint8_t raceId;
    };

    /**
     * One row of `Libs/Tables/item/body_subpart.xml`.
     *
     * The engine reports a hit as a subpart -- `C_HealthValueEffect` carries
     * one -- and this is the step from that to the limb.
     */
    struct BodySubpartEntry {
        std::string_view name;
        std::uint8_t id;
        std::uint8_t bodyPartId;
    };

    inline constexpr std::uint8_t kNoBodyPart = 0;
    inline constexpr std::uint8_t kHumanRace  = 0;

    /** Sorted by id. */
    extern const std::vector<BodyPartEntry> g_BodyParts;

    /** Sorted by id. */
    extern const std::vector<BodySubpartEntry> g_BodySubparts;

    inline const BodyPartEntry *FindBodyPart(std::uint8_t id) {
        for (const BodyPartEntry &part : g_BodyParts) {
            if (part.id == id) {
                return &part;
            }
        }
        return nullptr;
    }

    /** The limb a subpart belongs to, or `kNoBodyPart` for -1 and for an id no row has. */
    inline std::uint8_t BodyPartOfSubpart(std::int32_t subpartId) {
        for (const BodySubpartEntry &subpart : g_BodySubparts) {
            if (subpart.id == subpartId) {
                return subpart.bodyPartId;
            }
        }
        return kNoBodyPart;
    }

    /** Whether this row is one of the six human limbs a script can name. */
    inline bool IsHumanLimb(const BodyPartEntry &part) {
        return part.raceId == kHumanRace && !part.scriptName.empty();
    }

    /** One of the six human limbs a script can name, or null. */
    inline const BodyPartEntry *FindHumanLimb(std::uint8_t id) {
        const BodyPartEntry *part = FindBodyPart(id);
        return part != nullptr && IsHumanLimb(*part) ? part : nullptr;
    }

    /**
     * The human limb whose injury this buff is, or null.
     *
     * Only human rows are searched: horses, dogs and the game animals reuse
     * the same six buffs for their own parts, so the id alone does not say
     * which limb a human is missing.
     */
    inline const BodyPartEntry *FindHumanLimbByInjuryBuff(const RPC::BuffId &buff) {
        for (const BodyPartEntry &part : g_BodyParts) {
            if (IsHumanLimb(part) && part.injuryBuff == buff) {
                return &part;
            }
        }
        return nullptr;
    }
} // namespace KCDC::Shared::Game
